const active=()=>state.shifts.find(s=>s.status==='active'),currentRun=()=>state.runs.find(r=>r.status==='active');
const bag='<path d="M3.5 7.5 16 6.5 20 10 20.5 21 7 21.5 3 18zM3.5 7.5 7 11 20 10M7 11v10.5M3 18l2-2 2 5.5M4 8l1 8"/><path d="M8 7V4.8a2.8 2.8 0 0 1 5.6 0v2M10 10.8V8a2.8 2.8 0 0 1 5.6 0v2.3"/>';
