const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]}</svg>`;
function notify(t){$('#notice').textContent=t;setTimeout(()=>$('#notice').textContent='',5000);}
function dialog(title,body,submit,label='Save',closeLabel='Cancel'){const d=$('#modal');d.oncancel=null;d.innerHTML=`<form><h2>${title}</h2>${body}<p class="error" role="alert"></p><div class="actions"><button type="button" data-close>${closeLabel}</button>${submit?`<button class="primary" type="submit">${label}</button>`:''}</div></form>`;d.querySelector('[data-close]').onclick=()=>d.close();if(submit)d.querySelector('form').onsubmit=async e=>{e.preventDefault();const btn=d.querySelector('[type=submit]');btn.disabled=true;try{const form=e.target;await submit(new FormData(form));if(d.querySelector('form')===form)d.close();}catch(err){d.querySelector('.error').textContent=err.message;}finally{btn.disabled=false;}};d.showModal();}
async function mutate(fn){if(busy)throw Error('Please wait for the previous save.');busy=true;const next=structuredClone(state);try{fn(next);completeRuns(next);await save(next);state=next;render();if(!demoMode)syncNotifications(state).catch(()=>{});}finally{busy=false;}}
function audit(s,entityId,action,before,after){s.audit.push({id:id(),entityId,action,before,after,at:now()});}
function header(title,description,action=''){return `<div class="heading-row"><div><h1>${title}</h1><div class="muted">${description}</div></div>${action}</div>`;}
function metric(label,value,detail){return `<div class="metric"><div class="muted">${label}</div><div class="number">${value}</div><small>${detail}</small></div>`;}
function deliveriesFor(s){return state.deliveries.filter(d=>d.shiftId===s.id);}
function deliveryCard(d,i){if(d.status==='delivered'&&!expandedCompleted.has(d.id))return `<div class="card completed-row"><div><strong>${esc(d.name||'Delivery')}</strong><div class="muted">${esc(d.address)} · ${time(d.completedAt)}</div></div><button data-action="toggle-completed" data-id="${d.id}">Expand</button></div>`;const pending=d.status==='pending',ready=d.status==='ready',done=d.status==='delivered',batchWaiting=d.batchId&&state.deliveries.some(x=>x.batchId===d.batchId&&x.status==='pending');return `<div class="card delivery ${d.scheduledAt?'scheduled-delivery':''}"><span class="stop">${i+1}</span><div class="content"><div class="row"><h3>${esc(d.name||'Delivery')}</h3><span class="badge ${d.scheduledAt?'scheduled':done?'completed-badge':''}">${d.scheduledAt?icon('shift'):''}${done?'Delivered':d.scheduledAt?'Scheduled':'Standard'}</span></div>${d.needsSignature||d.hasAlcohol?'<span class="badge signature-tag">Needs signature</span>':''}<div class="address">${esc(d.address)}</div>${dogWarning(d.address)}${d.hasAlcohol?'<div class="alcohol-reminder">Alcohol: bring the receipt for the customer to sign upon delivery.</div>':''}${d.hasColdItems?'<div class="cold-item-note">Drinks / ice cream included in this order</div>':''}<div class="muted">${pending?'Pending · being prepared':ready?'Ready · bagged for delivery':done?'Completed':'Active · out for delivery'}</div>${d.scheduledAt?`<p class="muted">Requested arrival · ${date(d.scheduledAt)}, ${time(d.scheduledAt)}</p>`:''}${d.completedAt?`<p class="muted">Delivered · ${time(d.completedAt)}</p>`:''}${d.ticket?`<div class="muted">Ticket ${esc(d.ticket)}</div>`:''}<div class="actions">${done?`<button data-action="toggle-completed" data-id="${d.id}">Collapse</button>`:''}<button class="outline" data-action="edit-address" data-id="${d.id}">Edit address</button>${pending?`<button class="primary" data-action="ready" data-id="${d.id}">Mark ready</button>`:ready?`<button class="primary" data-action="route" data-id="${d.batchId||d.id}" ${batchWaiting?'disabled title="Mark all batch stops ready first"':''}>Start ${d.batchId?'batch':'delivery'}</button><button data-action="pending" data-id="${d.id}">Still preparing</button>`:done?`<button data-action="undo" data-id="${d.id}">Undo delivered</button>`:`<button class="primary" data-action="delivered" data-id="${d.id}">Delivered</button><button data-action="navigate" data-id="${d.id}">Navigate</button>`}${!pending?`<button data-action="message" data-id="${d.id}" ${!d.phone?'disabled':''}>Message</button>`:''}${pending||ready?`<button class="link" data-action="edit" data-id="${d.id}">Edit</button><button class="link" data-action="cancel" data-id="${d.id}">Remove</button>`:''}</div></div></div>`;}
function deliveryItems(ds){const groups=new Map();for(const d of ds){const key=d.batchId||d.id;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(d);}return [...groups].map(([key,group],i)=>{if(!group[0].batchId)return deliveryCard(group[0],i);const all=state.deliveries.filter(d=>d.batchId===key&&d.status!=='canceled').sort((a,b)=>(a.batchPosition??1e6)-(b.batchPosition??1e6)),open=expandedBatches.has(key),done=all.filter(d=>d.status==='delivered').length;return `<section class="card batch-summary ${all.some(d=>d.scheduledAt)?'scheduled-delivery':''}"><div class="row batch-header"><div><h3>Batch delivery · ${all.length} stops</h3><span class="muted">${done} completed · ${all.filter(d=>d.status==='pending').length} pending · ${all.filter(d=>d.status==='ready').length} ready</span></div><button class="primary batch-toggle" data-action="toggle-batch" data-id="${key}" aria-expanded="${open}">${open?'Collapse':'View stops'}</button></div>${all.every(d=>d.status==='ready')?`<div class="actions"><button class="primary" data-action="route" data-id="${key}">Start batch</button></div>`:''}${open?`<div class="batch-stops"><div class="batch-route-actions"><button class="primary" data-action="plan-batch" data-id="${key}">Customize route</button><button class="outline" data-action="reopen-route" data-id="${key}">View route</button></div><hr class="batch-divider">${state.runs.some(r=>r.batchId===key&&r.status==='active')?'<p class="muted">This batch is underway. A new order joins the run after Mark ready. Reopen navigation for the new stop; the existing Maps route does not update automatically.</p>':''}${canAppendBatch(key)?`<div class="batch-add"><button class="outline" data-action="append-batch" data-id="${key}">+Add order</button></div>`:''}${all.map(deliveryCard).join('')}</div>`:''}</section>`;}).join('');}
function shiftView(){const s=active(),done=s?deliveriesFor(s).filter(d=>d.status==='delivered').length:0,run=currentRun(),ready=s?deliveriesFor(s).filter(d=>d.status==='ready'):[];return header('Your shift, in order.','A little less juggling. A smoother delivery night.')+`<section class="hero"><div><div class="eyebrow">${s?'ON THE CLOCK':'READY WHEN YOU ARE'}</div><h2>${s?'Have a good shift.':'A fresh start for every shift.'}</h2><p>${s?`Started at ${time(s.startedAt)} · Odometer ${s.startOdometer.toLocaleString()} mi. Your records stay on this device.`:'Start with your odometer reading. We’ll keep your deliveries and mileage together, from the first bag to the last stop.'}</p><div class="actions"><button class="primary" data-action="${s?'add':'start'}">${s?'+ Add delivery':'Start shift →'}</button>${s?'<button class="outline" data-action="end">End shift</button>':''}</div></div>${icon('deliveries')}</section><div class="metrics">${metric('Deliveries completed',done,s?'This shift':'Your next shift awaits')}${metric('Delivery runs',s?state.runs.filter(r=>r.shiftId===s.id).length:0,'Single and batch trips')}${metric('Starting odometer',s?s.startOdometer.toLocaleString():'—','Actual miles at shift end')}</div><div class="grid-two"><section><div class="section-head"><h2>${run?'Out for delivery':'Ready for delivery'}</h2><span class="badge">${run?run.deliveryIds.filter(x=>state.deliveries.find(d=>d.id===x)?.status!=='delivered').length:ready.length} orders</span></div>${run?`<div class="card"><h3>Your current run</h3><p class="muted">Started ${time(run.startedAt)} · ${run.deliveryIds.length} delivery stops</p><div class="actions"><button data-action="deliveries">View deliveries</button></div></div>`:ready.length?deliveryItems(ready)+`<button class="primary" data-action="route">Prepare route →</button>`:`<div class="card empty">${icon('deliveries')}<h3>No bags on the counter yet.</h3><p class="muted">Add each prepared order here when you pick it up. One order or a whole batch—we’ll keep it organized.</p><button class="outline" data-action="${s?'add':'start'}">${s?'Add your first delivery':'Start your first shift'}</button></div>`}</section><aside><div class="section-head"><h2>A note for the road</h2></div><div class="card"><div class="eyebrow">YOUR MILEAGE, ACCURATELY</div><h3>The odometer tells the story.</h3><p class="muted">Start and end readings give you actual shift mileage—including the drive back to the restaurant.</p><hr style="border:0;border-top:1px solid #e2e4d9;margin:20px 0"><div class="private">◌ PRIVATE BY DESIGN</div><p class="muted">Your reimbursement calculations stay in your reports. Mike receives actual miles, without the private numbers.</p></div></aside></div><p class="welcome-note">Made for the rhythm of your delivery night.</p>`;}
function deliveriesView(){const s=active(),ds=s?deliveriesFor(s).filter(d=>d.status!=='canceled'):[],isComplete=d=>d.batchId?ds.filter(x=>x.batchId===d.batchId).every(x=>x.status==='delivered'):d.status==='delivered',live=prioritizeOngoing(ds.filter(d=>!isComplete(d)),state.runs),done=ds.filter(isComplete).sort((a,b)=>Date.parse(b.completedAt)-Date.parse(a.completedAt));return header('The delivery counter.','Pending → Ready → Active → Completed',s?'<div class="actions"><button class="link" data-action="navigate-home">Directions to restaurant</button><button class="primary" data-action="add">+ Add delivery</button></div>':'')+`<div class="hint">Enter tickets while food is being prepared. Mark each order ready when it’s bagged, then start its delivery or batch. Scheduled times never start a run automatically.</div><div class="section-head"><h2>New & ongoing deliveries</h2><span class="badge">${live.filter(d=>d.status!=='delivered').length} remaining</span></div>${live.length?deliveryItems(live):'<div class="card empty"><h3>No orders waiting.</h3><p class="muted">Add tickets whenever you’re ready—even before the food is bagged.</p></div>'}<div class="section-head completed-heading"><h2>Completed deliveries</h2><span class="badge completed-badge">${done.length}</span></div>${done.length?deliveryItems(done):'<p class="muted">Completed orders will appear here.</p>'}`;}
function historyView(){const ss=state.shifts.filter(s=>s.status==='finalized').sort((a,b)=>Date.parse(b.startedAt)-Date.parse(a.startedAt));for(const id of selectedShifts)if(!ss.some(s=>s.id===id))selectedShifts.delete(id);return header('Every shift, kept.','Each run records one departure with a single delivery or a batch. New runs close after the final delivery.')+(ss.length?`<div class="history-selection"><label class="checkbox-label"><input type="checkbox" id="select-all-shifts" ${ss.every(s=>selectedShifts.has(s.id))?'checked':''}> Select all shifts</label><button class="danger" data-action="delete-selected" ${selectedShifts.size?'':'disabled'}>Delete selected (${selectedShifts.size})</button><button data-action="clear-selection">Clear selection</button></div><div class="card table-wrap history-list"><table><thead><tr><th>Select</th><th>Date</th><th>Shift time</th><th>Miles</th><th>Deliveries</th><th>Single / batch runs</th><th>Actions</th></tr></thead><tbody>${ss.map(s=>`<tr><td><input class="shift-selector" type="checkbox" data-shift-selection="${s.id}" aria-label="Select shift ${esc(date(s.startedAt))}, ${esc(time(s.startedAt))}" ${selectedShifts.has(s.id)?'checked':''}></td><td>${date(s.startedAt)}</td><td>${time(s.startedAt)} – ${localDate(s.startedAt)!==localDate(s.endedAt)?date(s.endedAt)+' ':''}${time(s.endedAt)}</td><td>${miles(s)}</td><td>${deliveriesFor(s).filter(d=>d.status==='delivered').length}</td><td>${runCounts(s).single} / ${runCounts(s).batch}</td><td><div class="row"><button class="compact" data-action="report" data-id="${s.id}">Send report</button><button class="compact outline" data-action="run-details" data-id="${s.id}">Runs</button><button class="compact outline" data-action="correct" data-id="${s.id}">Edit</button></div></td></tr>`).join('')}</tbody></table></div>`:'<div class="card empty"><h3>Your first shift starts the story.</h3><p class="muted">Completed shifts will appear here, with actual mileage and a report you can prepare again.</p></div>');}
const filtered=(dates=range)=>state.shifts.filter(s=>s.status==='finalized'&&(!dates.from||localDate(s.startedAt)>=dates.from)&&(!dates.to||localDate(s.startedAt)<=dates.to));
function reportDetails(shifts){const ids=new Set(shifts.map(s=>s.id)),scheduled=shifts.flatMap(s=>deliveriesFor(s)).filter(d=>d.status==='delivered'&&d.scheduledAt).sort((a,b)=>Date.parse(b.completedAt||b.scheduledAt)-Date.parse(a.completedAt||a.scheduledAt)),batches=runsByKind(state.runs,[...ids],'batch'),singles=runsByKind(state.runs,[...ids],'single'),page=paginate(detailFilter==='scheduled'?scheduled:detailFilter==='single'?singles:batches,detailPage);detailPage=page.page;const stats=scheduledStats(scheduled);return `<div class="period-switch" role="group" aria-label="Delivery report details"><button data-action="detail-filter" data-id="scheduled" aria-pressed="${detailFilter==='scheduled'}" class="${detailFilter==='scheduled'?'primary':''}">Scheduled</button><button data-action="detail-filter" data-id="single" aria-pressed="${detailFilter==='single'}" class="${detailFilter==='single'?'primary':''}">Single</button><button data-action="detail-filter" data-id="batch" aria-pressed="${detailFilter==='batch'}" class="${detailFilter==='batch'?'primary':''}">Batch</button></div><section class="card report-details"><h2>${detailFilter==='scheduled'?'Scheduled delivery timing':detailFilter==='single'?'Single delivery records':'Batch delivery records'}</h2>${detailFilter==='scheduled'?`<h3>${stats.onTime} / ${stats.total} delivered by requested time</h3><p class="muted">At or before requested time; provisional rule without a grace period. Totals cover the whole selected date range.</p>`:''}${page.items.map(item=>detailFilter==='scheduled'?`<div class="timing-row"><span>${date(item.scheduledAt)} · requested ${time(item.scheduledAt)}</span><span>${item.completedAt?'Delivered '+time(item.completedAt):'Completion time unavailable'}</span></div>`:`<div class="timing-row"><div><strong>${date(item.startedAt)} · ${time(item.startedAt)}</strong><div class="muted">${item.deliveryIds.length} ${item.deliveryIds.length===1?'stop':'stops'} · ${item.completedAt?'Deliveries completed '+time(item.completedAt):item.status==='returned'?'Returned '+time(item.returnedAt):'In progress'}</div></div><button class="compact" data-action="run-details" data-id="${item.shiftId}">View shift runs</button></div>`).join('')||'<p class="muted">No matching records in this date range.</p>'}<div class="pagination" aria-label="Report pages"><button data-action="detail-page" data-id="-1" ${page.page===0?'disabled':''} aria-label="Previous records">← Previous</button><span class="muted">${page.total?`${page.page*10+1}–${Math.min((page.page+1)*10,page.total)} of ${page.total}`:'0 records'}</span><button data-action="detail-page" data-id="1" ${page.page===page.pages-1?'disabled':''} aria-label="Next records">Next →</button></div></section>`;}

function reportsView(){const ss=filtered(),total=ss.reduce((a,s)=>a+miles(s),0),paid=ss.filter(s=>s.rate!=null);return header('Your numbers. Your records.','A private view of your mileage and expected reimbursement.')+`<div class="card"><div class="form-grid"><div><label for="from">From date</label><div class="date-input-wrap"><input id="from" type="date" value="${range.from}"></div></div><div><label for="to">Through date</label><div class="date-input-wrap"><input id="to" type="date" value="${range.to}"></div></div></div><div class="actions"><button data-action="filter">Apply date range</button><button data-action="export" class="primary">Export CSV</button></div><p class="muted">Shifts are grouped by their local start date. Customer information is excluded.</p></div><div class="period-switch" role="group" aria-label="Report view">${['weekly','monthly','yearly'].map(v=>`<button data-period="${v}" aria-pressed="${reportView===v}" class="${reportView===v?'primary':''}">${v[0].toUpperCase()+v.slice(1)}</button>`).join('')}${reportView==='custom'?'<span class="muted">Custom dates</span>':''}</div><div class="metrics">${metric('Actual miles',Number(total.toFixed(3)),`${ss.length} completed shifts`)}${metric('Completed deliveries',ss.reduce((a,s)=>a+deliveriesFor(s).filter(d=>d.status==='delivered').length,0),'In selected shifts')}${metric('Expected reimbursement','$'+paid.reduce((a,s)=>a+reimbursement(s),0).toFixed(2),paid.length===ss.length?'Private · configured rate':`${ss.length-paid.length} shifts have no rate`)}</div><div class="hint">Estimated road miles are unavailable until a routing data source is chosen. Missing estimates are not treated as zero.</div><div class="card"><h2>Single and batch runs</h2><p>${ss.reduce((n,s)=>n+runCounts(s).single,0)} single runs · ${ss.reduce((n,s)=>n+runCounts(s).batch,0)} batch runs</p><p class="muted">Open History → Runs for the individual stops and recorded times.</p></div>${reportDetails(ss)}<div class="card table-wrap"><table><thead><tr><th>Shift</th><th>Actual miles</th><th>Rate / mi</th><th>Expected</th></tr></thead><tbody>${ss.map(s=>`<tr><td>${date(s.startedAt)}</td><td>${miles(s)}</td><td>${s.rate==null?'—':'$'+s.rate.toFixed(2)}</td><td>${reimbursement(s)==null?'—':'$'+reimbursement(s).toFixed(2)}</td></tr>`).join('')||'<tr><td colspan="4">No completed shifts in this date range.</td></tr>'}</tbody></table></div>`;}
function settingsView(){return header('Make it yours.','A few details to make every shift easier.')+`${settingsEditing?`<form id="settings-form" class="card"><div class="row"><h2>The essentials</h2><button type="button" data-action="settings-cancel">Cancel</button></div><label for="restaurant">Restaurant address</label><input id="restaurant" name="restaurant" value="${esc(state.settings.restaurant)}" placeholder="Street address, city, state"><label for="mike">Mike’s phone number</label><input id="mike" name="mike" type="tel" inputmode="tel" autocomplete="tel" value="${esc(state.settings.mike)}" placeholder="Enter privately on this device"><label for="helpPhone">Tony’s help phone number</label><input id="helpPhone" name="helpPhone" type="tel" inputmode="tel" value="${esc(state.settings.helpPhone||'')}"><label for="rate">Private reimbursement rate ($ per mile)</label><input id="rate" name="rate" inputmode="decimal" type="number" min="0" step="0.001" value="${state.settings.rate??''}" placeholder="Your employer’s agreed rate"><p class="muted">No legal rate is assumed. Changes apply to new shifts; previous shifts keep their original rate.</p><button class="primary" type="submit">Save settings</button><p class="error" role="alert"></p></form>`:`<div class="card"><div class="row"><h2>The essentials</h2><button data-action="settings-edit">Edit</button></div><dl class="essentials"><dt>Restaurant address</dt><dd>${esc(state.settings.restaurant||'Not set')}</dd><dt>Mike’s phone number</dt><dd>${esc(state.settings.mike||'Not set — enter once using Edit')}</dd><dt>Private reimbursement rate</dt><dd>${state.settings.rate==null?'Not set':'$'+state.settings.rate.toFixed(3)+' per mile'}</dd></dl><p class="muted">Saved on this device. Mike’s number is reused for every report.</p><button class="outline" data-action="restore-contact-defaults">Use restaurant defaults</button></div>`}<div class="card"><h2>App updates</h2><details class="icon-help"><summary>Refresh the Home Screen icon</summary><ol><li>Download a full backup here and confirm the file is in Files.</li><li>Open this same app address in Safari and add it to the Home Screen again, with Open as Web App enabled. Keep the old icon for now.</li><li>Open the new icon. Check the version and your records. If its storage is empty, use Restore backup.</li><li>Only after checking the new copy, remove the old icon. If iOS offers only Delete App, stop until the backup and restored records are verified.</li></ol><p class="muted">The icon is saved by iOS separately from app updates. Don’t clear Safari website data.</p></details><p class="muted">Installed version: ${VERSION}. Updates never delete your saved records.</p><button type="button" data-action="check-updates">Check for updates</button><h2 class="space">Records on this device</h2><p class="muted">Customer details, shift history, and Mike’s number are stored in this browser on this device, not synchronized online. This note describes storage location, not the status of the last save.</p><h3>Keep a copy.</h3><p class="muted">Records live in this browser’s local database. They can be lost if storage is cleared or your device is lost. Save a backup in Files or iCloud Drive regularly.</p><div class="actions"><button data-action="backup" class="primary">Download full backup</button><button data-action="restore">Restore backup</button></div><p class="muted">Full backups contain saved customer details. Keep them private.</p><input type="file" id="restore-file" accept="application/json,.json" hidden></div><div class="card"><div class="row"><h2>Saved customers</h2><button class="danger" data-action="delete-all-customers" ${state.customers.length?'':'disabled'}>Delete all</button></div><p class="muted">${state.customers.length} customer records on this device. Removing a customer also redacts their historical contact details while retaining shift totals.</p>${state.customers.map(c=>`<div class="row"><span>${esc(c.name)}</span><button class="link" data-action="delete-customer" data-id="${c.id}">Delete customer</button></div>`).join('')}</div><div class="card"><h2>Try three months of sample records</h2><p class="muted">Wednesday, Thursday, and Friday shifts, with singles, batches, scheduled deliveries and varied mileage. Sample mode uses its own database; your real records stay separate.</p><a class="button-link" href="${demoMode?'?':'?demo=1'}">${demoMode?'Return to my real records':'Explore sample records'}</a></div><div class="hint">Version ${VERSION} · iPhone test build. Address suggestions search locally saved addresses; new street lookup needs a connected map provider.</div>${notificationSettings()}<section class="card help-section"><h2>Need help? Ask Tony</h2><p class="muted">Text for questions—you’ll usually get a quick response. Call for urgent help.</p><button class="primary" data-action="help">Text or call Tony</button></section>`;}
function render(){const names={shift:'Shift',deliveries:'Deliveries',history:'History',reports:'Reports',tasks:'Tasks',settings:'Settings'};$('#app').innerHTML=`<div class="app-shell"><aside class="sidebar"><div class="brand"><img src="icon.svg" alt=""><div>Delivery Manager<small>ONE SHIFT AT A TIME</small></div></div><nav class="nav" aria-label="Main navigation">${Object.entries(names).map(([k,v])=>`<button data-tab="${k}" class="${tab===k?'selected':''}" ${tab===k?'aria-current="page"':''}>${icon(k)}${v}</button>`).join('')}</nav><footer>LOCAL RECORDS. CLEAR MIND.<br>Your night, a little more organized.<br>Version ${VERSION} · From ticket to doorstep</footer></aside><main class="main">${demoMode?'<div class="demo-banner"><strong>SAMPLE MODE — fictional records</strong><a href="?">Return to my records</a></div>':''}<div class="topline"><span>${new Date().toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'})}</span></div>${({shift:shiftView,deliveries:deliveriesView,history:historyView,reports:reportsView,tasks:tasksView,settings:settingsView}[tab])()}</main></div>`;document.querySelectorAll('[data-shift-selection]').forEach(c=>c.onchange=()=>{c.checked?selectedShifts.add(c.dataset.shiftSelection):selectedShifts.delete(c.dataset.shiftSelection);render();});if($('#select-all-shifts'))$('#select-all-shifts').onchange=e=>{state.shifts.filter(s=>s.status==='finalized').forEach(s=>e.target.checked?selectedShifts.add(s.id):selectedShifts.delete(s.id));render();};document.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{detailPage=0;reportView=b.dataset.period;range=periodRange(reportView);render();});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render();});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>handle(b.dataset.action,b.dataset.id).catch(e=>notify(e.message)));if($('#settings-form'))$('#settings-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{const r=f.get('rate');settingsEditing=false;await mutate(s=>s.settings={...s.settings,restaurant:f.get('restaurant').trim(),mike:f.get('mike').trim(),rate:r===''?null:Number(r),helpPhone:f.get('helpPhone').trim()});notify('Settings saved on this device.');}catch(err){notify(err.message);}};if($('#restore-file'))$('#restore-file').onchange=restoreFile;}
function readyGroups(){const s=active();if(!s)return [];const groups=new Map();for(const d of deliveriesFor(s).filter(d=>d.status==='ready').sort((a,b)=>(a.batchPosition??1e6)-(b.batchPosition??1e6))){const key=d.batchId||d.id;if(!groups.has(key))groups.set(key,{key,stops:[],kind:d.batchId?'batch':'single'});groups.get(key).stops.push(d);}return [...groups.values()].filter(g=>g.kind==='single'||!deliveriesFor(s).some(d=>d.batchId===g.key&&d.status==='pending'));}
function runCounts(shift){const runs=state.runs.filter(r=>r.shiftId===shift.id);return {single:runs.filter(r=>(r.kind|| (r.deliveryIds.length>1?'batch':'single'))==='single').length,batch:runs.filter(r=>(r.kind||(r.deliveryIds.length>1?'batch':'single'))==='batch').length};}
function pendingBatchSummary(ds){const groups=readyGroups();return groups.filter(g=>g.kind==='batch').map(g=>`<div class="card batch-summary"><div class="row batch-header"><div><h3>Batch delivery · ${g.stops.length} stops</h3><span class="muted">${g.stops.map(d=>esc(d.name||'Delivery')).join(' → ')}</span></div><button data-action="route" data-id="${g.key}">Prepare batch</button></div></div>`).join('');}
function chooseRun(groups){dialog('Choose a delivery run',`<p class="muted">Each saved batch stays together. Single orders start their own run.</p>${groups.map(g=>`<button class="run-choice" type="button" data-run-key="${g.key}"><strong>${g.kind==='batch'?'Batch delivery':'Single delivery'} · ${g.stops.length} ${g.stops.length===1?'stop':'stops'}</strong><small>${g.stops.map(d=>esc(d.name||d.address)).join(' → ')}</small></button>`).join('')}`,null);$('#modal').querySelectorAll('[data-run-key]').forEach(b=>b.onclick=()=>handle('route',b.dataset.runKey).catch(e=>notify(e.message)));}
function canAppendBatch(batchId){const shift=active();if(!shift)return false;const stops=state.deliveries.filter(d=>d.shiftId===shift.id&&d.batchId===batchId&&d.status!=='canceled');return stops.length>0&&(stops.some(d=>d.status!=='delivered')||state.runs.some(r=>r.shiftId===shift.id&&r.batchId===batchId&&r.status==='active'));}
function currentBatch(){return [...new Set(state.deliveries.filter(d=>d.shiftId===active()?.id&&d.batchId).map(d=>d.batchId))].find(canAppendBatch)||null;}
function appendToBatch(batchId){if(!canAppendBatch(batchId))throw Error('No current batch is available.');addDelivery(null,null,batchId);}

function chooseDeliveryType(){const batch=currentBatch();dialog('What are you taking out?',`<p class="muted">One order, or a group you’ll deliver in one run?</p><button type="button" class="run-choice primary" id="choose-single"><strong>Single Delivery</strong><small>Add one customer and destination.</small></button><button type="button" class="run-choice primary" id="choose-batch"><strong>Batch Delivery</strong><small>Create a new batch, one stop at a time.</small></button><button type="button" class="run-choice existing-batch-choice" id="append-current-batch" ${batch?'':'disabled'}><strong>Add to Existing Batch</strong><small>${batch?'Choose a current batch for another order.':'Create a batch first to add orders to it.'}</small></button>${batchDraft?'<button type="button" id="resume-batch">Resume unfinished batch</button>':''}`,null);$('#choose-single').onclick=()=>addDelivery();$('#choose-batch').onclick=()=>{if(!batchDraft)batchDraft={shiftId:active().id,stops:[]};batchReview();};if($('#resume-batch'))$('#resume-batch').onclick=batchReview;$('#append-current-batch').onclick=()=>{const batches=[...new Set(state.deliveries.filter(d=>d.shiftId===active()?.id&&d.batchId).map(d=>d.batchId))].filter(canAppendBatch);if(batches.length===1)return appendToBatch(batches[0]);dialog('Choose an existing batch',batches.map((key,i)=>`<button type="button" class="run-choice" data-choose-existing="${key}"><strong>Batch ${i+1}</strong><small>${state.deliveries.filter(d=>d.batchId===key&&d.status!=='canceled').map(d=>esc(d.name||d.address)).join(' · ')}</small></button>`).join(''),null);$('#modal').querySelectorAll('[data-choose-existing]').forEach(b=>b.onclick=()=>appendToBatch(b.dataset.chooseExisting));};}
function batchReview(){if(!batchDraft||batchDraft.shiftId!==active()?.id){batchDraft={shiftId:active()?.id,stops:[]};}dialog('Build your batch',`<p class="muted">${batchDraft.stops.length} stops added. Add at least two stops before saving. These draft stops aren’t counted as deliveries yet.</p><div>${batchDraft.stops.map((d,i)=>`<div class="draft-stop"><span>${i+1}. ${esc(d.name||'Delivery')}<small>${esc(d.address)}${d.scheduledAt?' · '+time(d.scheduledAt):''}</small></span><button type="button" data-remove-stop="${i}" aria-label="Remove stop ${i+1}">Remove</button></div>`).join('')}</div><div class="actions"><button type="button" id="batch-add-stop">+ Add stop</button></div><p class="muted">Cancel keeps this draft for this session; choose Add delivery → Resume unfinished batch to return. Reloading discards unsaved stops.</p>`,async()=>{if(batchDraft.stops.length<2)throw Error('Add at least two stops for a batch.');if(active()?.id!==batchDraft.shiftId)throw Error('This draft belongs to a different shift.');const batchId=id(),shiftId=batchDraft.shiftId;await mutate(v=>{for(const {remember,...details} of batchDraft.stops){let customerId=null;if(remember){let c=v.customers.find(c=>c.name===details.name&&c.address===details.address&&c.phone===details.phone);if(!c){c={id:id(),name:details.name,address:details.address,phone:details.phone};v.customers.push(c);}customerId=c.id;}v.deliveries.push({id:id(),shiftId,customerId,...details,batchId,deliveryMode:'batch',enteredAt:now(),status:'pending'});}});batchDraft=null;notify('Batch saved as pending. Mark stops ready as they are bagged.');},'Save batch');$('#batch-add-stop').onclick=()=>addDelivery(null,details=>{batchDraft.stops.push(details);batchReview();});$('#modal').querySelectorAll('[data-remove-stop]').forEach(b=>b.onclick=()=>{batchDraft.stops.splice(Number(b.dataset.removeStop),1);batchReview();});}
function showRunDetails(shiftId){const runs=state.runs.filter(r=>r.shiftId===shiftId);dialog('Delivery run records',runs.length?runs.map((r,i)=>`<section class="card"><h3>Run ${i+1} · ${(r.kind||(r.deliveryIds.length>1?'batch':'single'))==='batch'?'Batch delivery':'Single delivery'}</h3><p class="muted">${time(r.startedAt)} → ${r.completedAt?'Deliveries completed '+time(r.completedAt):r.returnedAt?'Returned '+time(r.returnedAt):'In progress'}</p><ol>${r.deliveryIds.map(id=>{const d=state.deliveries.find(d=>d.id===id);return d?`<li><strong>${esc(d.name||'Delivery')}</strong><div class="muted">${esc(d.address)}</div><button type="button" class="link history-edit-address" data-history-address="${d.id}">Edit address</button><small class="delivery-timestamp">${d.completedAt?'Delivered '+time(d.completedAt):esc(d.status)}${d.scheduledAt?' · Requested '+time(d.scheduledAt):''}</small></li>`:'<li>Delivery unavailable</li>';}).join('')}</ol></section>`).join(''):'<p class="muted">No departed runs were recorded for this shift.</p>',null,'Save','Done');$('#modal').querySelectorAll('[data-history-address]').forEach(b=>b.onclick=()=>editAddress(b.dataset.historyAddress));}

function addDelivery(existing,onAdded,targetBatch=null){if(!active())return;dialog(existing?'Edit delivery':onAdded?`Batch · stop ${batchDraft.stops.length+1}`:targetBatch?'Add order to batch':'Single delivery',`<div class="scan-controls"><button type="button" class="primary" id="scan-ticket">📷 Scan ticket</button><input id="ticket-photo" type="file" accept="image/*" capture="environment" hidden><p class="muted">Photograph the ticket close up. Photos are read on this device and are not saved or uploaded. Review all filled details.</p><p id="scan-status" role="status" aria-live="polite"></p></div><label for="customer">Customer name</label><input id="customer" autocapitalize="words" name="name" value="${esc(existing?.name||'')}" autocomplete="off" placeholder="Enter customer name"><div class="suggestions" id="suggestions"></div><label for="phone">Customer phone</label><input id="phone" name="phone" type="tel" inputmode="tel" autocomplete="tel" value="${esc(existing?.phone||'')}" placeholder="Optional — needed for a text"><label for="address">Delivery address (include unit)</label><input id="address" name="address" required value="${esc(existing?.address||'')}" placeholder="Street address and unit — Seattle, WA" autocomplete="street-address"><div id="address-suggestions" class="suggestions"></div><div><label for="ticket">Ticket number</label><input id="ticket" name="ticket" inputmode="numeric" pattern="[0-9]*" value="${esc(existing?.ticket||'')}"></div><fieldset class="cold-item-choice"><legend>Drinks or Ice Cream? (required)</legend><label><input type="radio" name="coldItems" value="yes" ${existing?.hasColdItems===true?'checked':''} required> Yes</label><label><input type="radio" name="coldItems" value="no" ${existing?.hasColdItems===false?'checked':''} required> No</label><div id="cold-details-wrap" ${existing?.hasColdItems?'':'hidden'}><label for="cold-details">Which drinks and ice cream?</label><textarea id="cold-details" name="coldDetails" maxlength="500" placeholder="For example: 2 Thai iced teas, 1 coconut ice cream" ${existing?.hasColdItems?'required':''}>${esc(existing?.coldItemDetails||'')}</textarea></div><p class="muted">These notes appear in the required confirmation before preparing a customer text.</p></fieldset><fieldset class="cold-item-choice alcohol-choice"><legend>Alcohol? (required)</legend><label><input type="radio" name="alcohol" value="yes" ${existing?.hasAlcohol===true?'checked':''} required> Yes</label><label><input type="radio" name="alcohol" value="no" ${existing?.hasAlcohol===false?'checked':''} required> No</label><div id="alcohol-reminder" class="alcohol-reminder" ${existing?.hasAlcohol?'':'hidden'}>Bring an alcohol receipt for the customer to sign upon delivery.</div></fieldset><label class="checkbox-label"><input name="needsSignature" type="checkbox" ${existing?.needsSignature?'checked':''}> Needs signature (tip / receipt)</label><label class="checkbox-label"><input id="scheduled-toggle" name="isScheduled" type="checkbox" ${existing?.scheduledAt?'checked':''}> Scheduled Delivery?</label><div id="scheduled-fields" ${existing?.scheduledAt?'':'hidden'}><label for="scheduled">Requested delivery time</label><select id="scheduled" name="scheduled">${Array.from({length:48},(_,i)=>{const h=Math.floor(i/2),m=i%2?30:0,value=String(h).padStart(2,'0')+':'+String(m).padStart(2,'0');const requested=existing?.scheduledAt?new Date(existing.scheduledAt):new Date();const selected=existing?.scheduledAt?requested.getHours()===h&&requested.getMinutes()===m:Math.ceil((requested.getHours()*60+requested.getMinutes())/30)*30%1440===h*60+m;return `<option value="${value}" ${selected?'selected':''}>${h%12||12}:${String(m).padStart(2,'0')} ${h<12?'AM':'PM'}</option>`;}).join('')}</select><p class="muted">Uses the shift start date: ${date(active().startedAt)}.</p></div><label><input name="remember" type="checkbox" checked style="width:auto;min-height:auto;margin-right:7px"> Save details for future local suggestions</label><p class="muted">Maps will receive the destination when you navigate. No customer directory is uploaded.</p>`,async f=>{const details={needsSignature:!!f.get('needsSignature'),name:f.get('name').trim(),address:f.get('address').trim(),phone:formatPhone(f.get('phone').trim()),ticket:f.get('ticket').trim(),hasColdItems:requiredYesNo(f.get('coldItems'),'Drinks or Ice Cream'),hasAlcohol:requiredYesNo(f.get('alcohol'),'Alcohol'),coldItemDetails:f.get('coldItems')==='yes'?String(f.get('coldDetails')||'').trim():'',scheduledAt:f.get('isScheduled')?scheduledInstant(active().startedAt,f.get('scheduled')):null};if(!details.address)throw Error('Enter a delivery address.');if(details.hasColdItems&&!details.coldItemDetails)throw Error('List the drinks and ice cream for this order.');if(onAdded){onAdded({...details,remember:!!f.get('remember')});return;}await mutate(s=>{let customerId=existing?.customerId||null;if(f.get('remember')){const c=s.customers.find(c=>c.address===details.address&&c.phone===details.phone&&c.name===details.name);customerId=c?.id||id();if(!c)s.customers.push({id:customerId,name:details.name,address:details.address,phone:details.phone});}if(existing){const d=s.deliveries.find(d=>d.id===existing.id);audit(s,d.id,'edit',structuredClone(d),details);if(details.hasColdItems!==!!d.hasColdItems||details.coldItemDetails!==(d.coldItemDetails||''))delete d.coldItemsConfirmedAt;Object.assign(d,details,{customerId});}else if(targetBatch)appendBatchOrder(s,active().id,targetBatch,{id:id(),customerId,...details,enteredAt:now()});else s.deliveries.push({id:id(),shiftId:active().id,customerId,...details,deliveryMode:'single',batchId:null,status:'pending',enteredAt:now()});});if(targetBatch)expandedBatches.add(targetBatch);render();notify(targetBatch?'Order added to batch as pending. Mark it ready when bagged.':'Delivery saved.');},existing?'Save changes':onAdded?'Add stop to batch':targetBatch?'Add to batch':'Add delivery');setupScanner();$('#phone').value=formatPhone($('#phone').value);$('#phone').oninput=e=>{const input=e.target,pos=input.selectionStart,before=input.value;input.value=formatPhone(before);if(pos===before.length)input.setSelectionRange(input.value.length,input.value.length);};$('#modal').querySelectorAll('[name=alcohol]').forEach(r=>r.onchange=()=>{$('#alcohol-reminder').hidden=$('#modal').querySelector('[name=alcohol]:checked').value!=='yes';});$('#modal').querySelectorAll('[name=coldItems]').forEach(r=>r.onchange=()=>{const yes=$('#modal').querySelector('[name=coldItems]:checked').value==='yes';$('#cold-details-wrap').hidden=!yes;$('#cold-details').required=yes;});$('#address').oninput=e=>{const q=e.target.value.toLowerCase().trim();const matches=q?state.customers.filter(c=>c.address.toLowerCase().includes(q)).filter((c,i,a)=>a.findIndex(x=>x.address===c.address)===i).slice(0,5):[];$('#address-suggestions').innerHTML=matches.map(c=>`<button type="button" data-address-id="${c.id}">${esc(c.address)}<small> · Saved on this device</small></button>`).join('');$('#address-suggestions').querySelectorAll('button').forEach(b=>b.onclick=()=>{$('#address').value=state.customers.find(c=>c.id===b.dataset.addressId).address;$('#address-suggestions').innerHTML='';});};$('#scheduled-toggle').onchange=e=>{$('#scheduled-fields').hidden=!e.target.checked;};$('#customer').oninput=e=>{const q=e.target.value.toLowerCase();const hits=q?state.customers.filter(c=>[c.name,c.address,c.phone].some(v=>v.toLowerCase().includes(q))).slice(0,4):[];$('#suggestions').innerHTML=hits.map(c=>`<button type="button" data-customer="${c.id}">${esc(c.name)} · ${esc(c.address)}</button>`).join('');$('#suggestions').querySelectorAll('button').forEach(b=>b.onclick=()=>{const c=state.customers.find(c=>c.id===b.dataset.customer);$('#customer').value=c.name;$('#address').value=c.address;$('#phone').value=formatPhone(c.phone);$('#suggestions').innerHTML='';});};}
function confirmMultipleShiftDeletion(shiftIds){const ids=[...new Set(shiftIds)],shifts=state.shifts.filter(s=>ids.includes(s.id)&&s.status==='finalized');if(!ids.length||shifts.length!==ids.length)return notify('Select completed shifts from History first.');const list=`<ul>${shifts.map(s=>`<li>${date(s.startedAt)} · ${time(s.startedAt)} · ${miles(s)} miles</li>`).join('')}</ul>`;dialog(`Delete ${ids.length} selected shifts? — 1 of 2`,`${list}<p>The selected shifts and their delivery/run records will be removed from History, Reports and exports. Saved customers and unselected shifts stay.</p><p class="muted">Download a backup in Settings first if you might need these records again.</p>`,async()=>{dialog(`Permanently delete ${ids.length} shifts? — 2 of 2`,`${list}<p>This is the final confirmation. There is no in-app undo; restoring an earlier backup is the recovery path. No reports will be sent.</p>`,async()=>{await mutate(v=>{deleteFinalizedShifts(v,ids);for(const id of ids)audit(v,id,'shift deleted',null,null);});selectedShifts.clear();tab='history';render();notify(`${ids.length} shifts deleted.`);},'Delete selected permanently');$('#modal').querySelector('[type=submit]').className='danger';},'Continue to final confirmation');}
function showHelp(){const phone=state.settings.helpPhone||DEFAULT_SETTINGS.helpPhone;if(!phone)return dialog('Tony’s help number is not set','<p>Tony’s phone number needs to be added to Settings before text and call links can work.</p>',null,'Save','Done');const sms=phoneURL(phone),tel=sms.replace('sms:','tel:');dialog('Need help? Ask Tony',`<p>Text for app questions. Tony will usually respond quickly.</p><a class="button-link" href="${esc(sms)}">Text Tony</a><p class="muted">For urgent help, call:</p><a class="button-link urgent-call" href="${esc(tel)}">Call Tony — urgent</a><p class="muted">${esc(phone)}. Your phone handles the call confirmation.</p>`,null,'Save','Done');}
function planBatch(batchId){let stops=state.deliveries.filter(d=>d.batchId===batchId&&d.status!=='canceled').sort((a,b)=>(a.batchPosition??1e6)-(b.batchPosition??1e6));if(!stops.length)throw Error('Batch not found.');dialog('Plan / reorder batch stops',`<p class="muted">Move stops with the arrows—for example, put stops 1 and 3 together. This saves the order before you open Apple Maps.</p><div class="hint">Geographic map preview is not connected yet. These are your entered addresses, not verified locations or an optimized route.</div><div id="batch-plan-list"></div>`,async()=>{await mutate(v=>{const ids=stops.map(d=>d.id);for(const [position,id] of ids.entries())v.deliveries.find(d=>d.id===id).batchPosition=position;for(const run of v.runs.filter(r=>r.batchId===batchId&&r.status==='active')){run.deliveryIds=ids.filter(id=>run.deliveryIds.includes(id));audit(v,run.id,'stop order changed',null,[...run.deliveryIds]);}});notify('Stop order saved. Reopen the route to update Maps.');},'Save stop order');const draw=()=>{$('#batch-plan-list').innerHTML=stops.map((d,i)=>`<div class="card"><strong>${i+1}. ${esc(d.name||'Delivery')}</strong><p class="muted">${esc(navigationAddress(d.address))} · ${esc(d.status)}</p><div class="actions"><button type="button" data-plan-up="${i}" aria-label="Move stop ${i+1} up" ${i===0?'disabled':''}>↑</button><button type="button" data-plan-down="${i}" aria-label="Move stop ${i+1} down" ${i===stops.length-1?'disabled':''}>↓</button></div></div>`).join('');$('#batch-plan-list').querySelectorAll('[data-plan-up],[data-plan-down]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.planUp??b.dataset.planDown),j=b.dataset.planUp!=null?i-1:i+1;[stops[i],stops[j]]=[stops[j],stops[i]];draw();});};draw();}

function confirmShiftDeletion(shiftId){const shift=state.shifts.find(s=>s.id===shiftId);if(!shift||shift.status!=='finalized')return notify('Only completed shifts can be deleted.');const description=`${date(shift.startedAt)} · ${time(shift.startedAt)}–${time(shift.endedAt)} · ${miles(shift)} miles`;dialog('Delete this shift? — 1 of 2',`<p><strong>${esc(description)}</strong></p><p>This will remove the shift, its deliveries, its runs and their correction records from History and Reports. Saved customers and other shifts stay.</p><p class="muted">You can download a backup in Settings before continuing. Cancel keeps the shift unchanged.</p>`,async()=>{dialog('Permanently delete shift? — 2 of 2',`<p><strong>${esc(description)}</strong></p><p>This is the final confirmation. This cannot be undone in the app; recovering the deleted records requires a backup created before deletion.</p><p>No report or text will be sent.</p>`,async()=>{await mutate(v=>{deleteFinalizedShift(v,shiftId);audit(v,shiftId,'shift deleted',null,null);});tab='history';render();notify('Shift deleted. History, report totals and exports updated.');},'Delete permanently');$('#modal').querySelector('[type=submit]').className='danger';},'Continue to final confirmation');}

function editAddress(deliveryId){const d=state.deliveries.find(d=>d.id===deliveryId);if(!d)throw Error('Delivery not found.');dialog('Edit delivery address',`<p class="muted">The delivery’s status, batch and completion time stay unchanged. A route already open in Maps will not change until you reopen it.</p><label for="edited-address">Delivery address</label><input id="edited-address" name="address" required value="${esc(d.address)}" autocomplete="street-address"><p class="muted">Seattle, WA is added for street-only entries. This correction applies to this order; saved customer details are unchanged.</p>`,async f=>{await mutate(v=>{const change=changeDeliveryAddress(v,deliveryId,f.get('address'));audit(v,deliveryId,'address correction',change.previous,change.address);});if(d.batchId&&active()?.id===d.shiftId){expandedBatches.add(d.batchId);render();}notify('Address saved. Reopen navigation to use the correction.');},'Save address');}
function reopenRoute(batchId){const all=state.deliveries.filter(d=>d.batchId===batchId&&d.status!=='canceled').sort((a,b)=>(a.batchPosition??1e6)-(b.batchPosition??1e6)),run=state.runs.find(r=>r.batchId===batchId&&r.status==='active'),remaining=all.filter(d=>['ready','active'].includes(d.status));const order=remaining.length?(run?run.deliveryIds.map(id=>remaining.find(d=>d.id===id)).filter(Boolean):remaining):all;showRoute(order);}


function firstStopURL(address){const u=new URL('https://maps.apple.com/directions');u.searchParams.set('destination',navigationAddress(address));u.searchParams.set('mode','driving');return u.href;}
function phoneURL(phone){const p=phone.replace(/[\s().-]/g,'');if(!/^\+?\d{7,15}$/.test(p))throw Error('Enter a valid phone number first.');return 'sms:'+p;}
function customerMessage(deliveryId,title){const delivery=state.deliveries.find(d=>d.id===deliveryId);if(!delivery)throw Error('Delivery not found.');phoneURL(delivery.phone);if(needsColdItemConfirmation(delivery)){return dialog('Did you include the drinks or ice cream?',`<div class="cold-confirmation-notes"><strong>Include these items:</strong><p>${esc(delivery.coldItemDetails||'Drinks / ice cream — no item details recorded')}</p></div><p>This order includes drinks or ice cream. Check that they were delivered with the food before preparing the customer’s text.</p><label class="checkbox-label"><input type="checkbox" name="itemsIncluded" required> I included all drinks and ice cream.</label>`,async f=>{if(!f.get('itemsIncluded'))throw Error('Confirm the drinks and ice cream were included.');await mutate(v=>{const d=v.deliveries.find(d=>d.id===deliveryId);d.coldItemsConfirmedAt=now();audit(v,d.id,'drinks / ice cream confirmed',null,d.coldItemsConfirmedAt);});compose(delivery.phone,CUSTOMER_MESSAGE,title);},'Confirm and prepare text');}return compose(delivery.phone,CUSTOMER_MESSAGE,title);}

function compose(phone,text,title){const url=phoneURL(phone);dialog(title,`<p class="muted">Review, copy, then open Messages. Paste the text and tap Send there.</p><label for="message-text">Message</label><textarea id="message-text">${esc(text)}</textarea><div class="actions"><button type="button" id="copy-message">Copy text</button><a class="primary" style="padding:13px;border-radius:12px;text-decoration:none" href="${esc(url)}">Open Messages</a></div><p class="muted">Recipient: ${esc(phone)}. Opening Messages does not confirm a text was sent.</p>`,null,'Save','Done');$('#copy-message').onclick=async()=>{try{await navigator.clipboard.writeText($('#message-text').value);$('#copy-message').textContent='Copied ✓';}catch{$('#message-text').select();notify('Copy is unavailable. Select and copy the text manually.');}};}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function backup(){download(`delivery-manager-${demoMode?'SAMPLE-':''}backup-${localDate(now())}.json`,JSON.stringify({format:'delivery-manager',version:1,exportedAt:now(),data:state},null,2),'application/json');notify('Backup downloaded. Store it somewhere safe.');}
async function restoreFile(e){const file=e.target.files[0];if(!file)return;try{if(file.size>20e6)throw Error('Backup is too large (maximum 20 MB).');const restored=validateBackup(JSON.parse(await file.text()));if(restored.demoSeedVersion)throw Error('Sample backups stay in sample mode and cannot replace real records.');dialog('Replace local records?',`<p>This backup contains ${restored.shifts.length} shifts, ${restored.deliveries.length} deliveries, and ${restored.customers.length} customers.</p><p class="muted">This replaces all current records. Download a current backup before continuing.</p><button type="button" id="prebackup">Download current backup</button>`,async()=>{await mutate(s=>{Object.keys(s).forEach(k=>delete s[k]);Object.assign(s,restored);});notify('Backup restored.');},'Replace and restore');$('#prebackup').onclick=backup;}catch(err){notify(err.message);}}
async function handle(action,key){const s=active(),d=state.deliveries.find(d=>d.id===key);if(action==='enable-push')return dialog('Enable lock-screen reminders',`<p>Allow notifications on this phone. The free reminder service stores only this phone’s notification connection and reminder schedule. Customer details, mileage and reports stay here.</p><label for="push-code">Driver setup code (ask Tony)</label><input id="push-code" name="code" type="password" autocomplete="off" required><p class="muted">You only need the code when enabling a phone. On iPhone, open the app from its Home Screen icon.</p>`,async f=>{await enableNotifications(f.get('code'),state);render();notify('Lock-screen reminders enabled. Use Send test notification to check this phone.');},'Enable notifications');if(action==='disable-push'){try{await disableNotifications(state);notify('Lock-screen reminders disabled.');}catch(e){notify('Disabled on this device. Online cancellation is pending; reconnect to finish.');}return render();}if(action==='test-push'){const sending=testNotification();render();try{await sending;render();notify('Test accepted. Check your notifications.');}catch(e){render();throw e;}return;}if(action==='retry-push'){await syncNotifications(state,true);render();return notify('Reminder schedule updated.');}if(action==='toggle-completed'){expandedCompleted.has(key)?expandedCompleted.delete(key):expandedCompleted.add(key);return render();}if(action==='navigate-home'){location.href=firstStopURL(state.settings.restaurant);return;}if(action==='delete-selected')return confirmMultipleShiftDeletion([...selectedShifts]);if(action==='clear-selection'){selectedShifts.clear();return render();}if(action==='plan-batch')return planBatch(key);if(action==='help')return showHelp();if(action==='restore-contact-defaults'){await mutate(v=>{v.settings.restaurant=DEFAULT_SETTINGS.restaurant;v.settings.mike=DEFAULT_SETTINGS.mike;});notify('Restaurant address and Mike’s number set to restaurant defaults.');return;}if(action==='check-updates'){if(busy)throw Error('Wait until saving finishes.');notify('Checking for updates…');const available=await checkForUpdates();if(!available)return notify('You’re on the latest version ('+VERSION+').');return dialog('Update available','<p>Your saved records will stay on this device. Unsaved form entries and batch drafts are not kept when reloading.</p>',async()=>reloadLatest(),'Reload latest version');}if(action==='edit-address')return editAddress(key);if(action==='reopen-route')return reopenRoute(key);if(action==='append-batch')return appendToBatch(key);if(action==='toggle-batch'){expandedBatches.has(key)?expandedBatches.delete(key):expandedBatches.add(key);return render();}if(action==='ready'||action==='pending'){await mutate(v=>{const x=v.deliveries.find(x=>x.id===key);const expected=action==='ready'?'pending':'ready';if(x.status!==expected)throw Error('This order has changed. Reopen it and try again.');audit(v,key,'preparation status',x.status,action);x.status=action==='ready'?'ready':'pending';if(action==='ready'&&x.batchId){const run=v.runs.find(r=>r.status==='active'&&r.batchId===x.batchId&&r.shiftId===x.shiftId);if(run){if(!run.deliveryIds.includes(x.id))run.deliveryIds.push(x.id);x.status='active';audit(v,run.id,'added ready batch stop',null,x.id);}}});return;}if(action==='detail-filter'){detailFilter=key;detailPage=0;return render();}if(action==='detail-page'){detailPage=Math.max(0,detailPage+Number(key));return render();}if(action==='settings-edit'){settingsEditing=true;return render();}if(action==='settings-cancel'){settingsEditing=false;return render();}if(action==='start')return dialog('Start your shift',`<p class="muted">Enter the odometer reading before you begin driving.</p>${(()=>{const last=state.shifts.filter(x=>x.status==='finalized').sort((a,b)=>Date.parse(b.endedAt)-Date.parse(a.endedAt))[0];return last?`<div class="hint">Last shift ended at <strong>${last.endOdometer.toLocaleString()} mi</strong> on ${date(last.endedAt)}. Reference only—enter your current reading below.</div>`:'';})()}<label for="start">Starting odometer (miles)</label><input id="start" name="start" inputmode="decimal" type="number" min="0" step="0.001" required autofocus>`,async f=>{await mutate(v=>{if(v.shifts.some(x=>x.status==='active'))throw Error('A shift is already active.');v.shifts.push({id:id(),status:'active',startedAt:now(),startOdometer:Number(f.get('start')),rate:v.settings.rate,timeZone:Intl.DateTimeFormat().resolvedOptions().timeZone});});notify('Shift started. Have a good night.');},'Start shift');if(action==='add')return chooseDeliveryType();if(action==='batch-review')return batchReview();if(action==='edit')return addDelivery(d);if(action==='deliveries'){tab='deliveries';return render();}if(action==='cancel')return dialog('Remove this delivery?',`<p>${esc(d.name)} · ${esc(d.address)}</p><label>Reason</label><input name="reason" required>`,async f=>mutate(v=>{const x=v.deliveries.find(x=>x.id===key);audit(v,key,'cancel',x.status,f.get('reason'));x.status='canceled';}),'Remove');if(action==='delivered'&&d.status!=='active')throw Error('Start the delivery run before marking it delivered.');if(action==='delivered')return dialog('Do you want to mark this order as delivered?',`<p><strong>${esc(d.name||'This delivery')}</strong></p><p class="muted">${esc(d.address)}</p>${d.hasAlcohol?'<div class="alcohol-reminder">Alcohol order: remember to have the customer sign the alcohol receipt upon delivery.</div>':''}<p>This records the delivery time. You can prepare the customer’s text next.</p>`,async()=>{await mutate(v=>{const x=v.deliveries.find(x=>x.id===key);if(x.status==='delivered')return;audit(v,key,'delivered',x.status,'delivered');x.status='delivered';x.completedAt=now();completeRuns(v,x.shiftId,x.completedAt);});completionNotes(d.id);return;},'Yes');if(action==='undo'){if(!s||d.shiftId!==s.id)throw Error('Use History for changes to a finalized shift.');await mutate(v=>{const x=v.deliveries.find(x=>x.id===key);audit(v,key,'undo delivery',x.completedAt,null);x.status=v.runs.some(r=>r.status==='active'&&r.deliveryIds.includes(key))?'active':'ready';delete x.completedAt;delete x.coldItemsConfirmedAt;});return notify('Delivery completion undone. Any text already sent cannot be recalled.');}if(action==='message')return customerMessage(d.id,'Message customer');if(action==='navigate'){if(d.status!=='active')throw Error('Start this delivery first.');if(hasDog(d.address))return dialog('Barking dog at this address',`<p>Be prepared for a barking dog before approaching the door.</p><p>${esc(d.address)}</p><a class="primary" href="${esc(firstStopURL(d.address))}">Continue to Apple Maps</a>`,null,'Save','Done');window.location.href=firstStopURL(d.address);return;}if(action==='route'){if(!state.settings.restaurant){tab='settings';render();return notify('Add the restaurant address first.');}const groups=readyGroups();if(!key&&groups.length>1)return chooseRun(groups);let stops=key?groups.find(g=>g.key===key)?.stops:groups[0]?.stops;if(!stops?.length)throw Error('No ready deliveries in this group.');const launch=async()=>{await mutate(v=>{if(v.runs.some(r=>r.status==='active'))throw Error('Finish the current deliveries first.');const ids=stops.map(d=>d.id);v.runs.push({id:id(),shiftId:s.id,deliveryIds:ids,kind:stops.length>1?'batch':'single',batchId:stops[0].batchId||null,status:'active',startedAt:now(),estimateStatus:'unavailable'});v.deliveries.filter(d=>ids.includes(d.id)).forEach(d=>d.status='active');});showRoute(stops);};if(stops.length===1){await launch();return;}dialog('Choose your stop order',`<p class="muted">Manual ordering for this first build. The route ends at the last delivery. Road-mile estimates are unavailable.</p>${stops.some(d=>d.hasAlcohol)?`<div class="alcohol-reminder">Bring alcohol receipts for customer signatures: ${stops.filter(d=>d.hasAlcohol).map(d=>esc(d.name||d.address)).join(', ')}.</div>`:''}<div id="stop-order"></div>`,launch,'Start deliveries');const draw=()=>{$('#stop-order').innerHTML=stops.map((d,i)=>`<div class="card"><div class="row"><span>${i+1}. ${esc(d.name||d.address)}</span><div><button type="button" data-up="${i}" aria-label="Move stop up" ${i===0?'disabled':''}>↑</button><button type="button" data-down="${i}" aria-label="Move stop down" ${i===stops.length-1?'disabled':''}>↓</button></div></div><small>${esc(d.address)}</small></div>`).join('');$('#stop-order').querySelectorAll('[data-up],[data-down]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.up??b.dataset.down),j=b.dataset.up!=null?i-1:i+1;[stops[i],stops[j]]=[stops[j],stops[i]];draw();});};draw();return;}if(action==='return'){const r=currentRun();if(r.deliveryIds.some(id=>!['delivered','canceled'].includes(state.deliveries.find(d=>d.id===id)?.status)))throw Error('Complete the remaining deliveries before closing this run.');await mutate(v=>{const x=v.runs.find(x=>x.id===r.id);x.status='returned';x.returnedAt=now();});return notify('Run complete. Back at the restaurant.');}if(action==='end'){const ending=shiftEndState(state,s.id);if(!ending.canEnd)throw Error(`${ending.unresolved.length} pending, ready, or active deliveries remain. Complete or remove them in Deliveries before ending your shift.`);return dialog('Finish your shift',`${ending.openRuns.length?'<div class="hint">All drop-offs are complete. Saving this shift also confirms you have finished the return trip and closes the delivery run. Enter your ending odometer after returning.</div>':''}<p class="muted">Starting odometer: ${s.startOdometer} mi. Actual mileage is used for your records and Mike’s report.</p><label for="finish-start">Starting odometer (miles)</label><input id="finish-start" name="start" inputmode="decimal" type="number" min="0" step="0.001" required value="${s.startOdometer}"><label for="end">Ending odometer (miles)</label><input id="end" name="end" inputmode="decimal" type="number" min="0" step="0.001" required>`,async f=>{const start=Number(f.get('start')),end=Number(f.get('end'));validateShiftMileage(state,s.id,start,end);await mutate(v=>{const x=v.shifts.find(x=>x.id===s.id);if(!shiftEndState(v,x.id).canEnd)throw Error('Unfinished deliveries remain.');validateShiftMileage(v,x.id,start,end);if(x.startOdometer!==start)audit(v,x.id,'starting odometer corrected at shift end',x.startOdometer,start);x.startOdometer=start;x.endOdometer=end;x.endedAt=now();x.status='finalized';for(const r of v.runs.filter(r=>r.shiftId===x.id&&r.status==='active')){r.status='returned';r.returnedAt=x.endedAt;audit(v,r.id,'return confirmed at shift end',null,r.returnedAt);}});tab='history';render();if(!demoMode){await syncNotifications(state,true).catch(()=>notify('Shift saved. Reminder cancellation will retry when connected.'));await handle('report',s.id);}else notify('Sample shift saved. Reports cannot be sent in sample mode.');},'Save completed shift');}if(action==='run-details')return showRunDetails(key);if(action==='report'){if(demoMode)throw Error('Sample reports cannot be sent to Mike.');const shift=state.shifts.find(x=>x.id===key);if(!state.settings.mike){tab='settings';render();return notify('Save Mike’s phone number first.');}return compose(state.settings.mike,mikeReport(shift,state.deliveries,state.runs),'Mike’s shift report');}if(action==='correct'){const x=state.shifts.find(x=>x.id===key);dialog('Edit shift',`<p class="muted">The original readings are retained in the correction log.</p><label>Starting odometer (miles)</label><input name="start" inputmode="decimal" type="number" min="0" step="0.001" required value="${x.startOdometer}"><label>Ending odometer (miles)</label><input name="end" inputmode="decimal" type="number" min="0" step="0.001" required value="${x.endOdometer}"><label for="shift-start">Shift start date and time</label><input id="shift-start" name="startedAt" type="datetime-local" required value="${localInput(x.startedAt)}"><label for="shift-end">Shift end date and time</label><input id="shift-end" name="endedAt" type="datetime-local" required value="${localInput(x.endedAt)}"><label for="correction-reason">Reason for correction (required)</label><input id="correction-reason" name="reason" required><div class="delete-shift-section"><h3>Remove an incorrect shift</h3><p class="muted">Deletes this shift and its delivery/run records after two confirmations. Saved customers are kept.</p><button type="button" class="danger" id="delete-shift">Delete shift</button></div>`,async f=>{const reason=correctionReason(f.get('reason'));const a=Number(f.get('start')),b=Number(f.get('end'));validateShiftMileage(state,key,a,b);const startedAt=new Date(f.get('startedAt')).toISOString(),endedAt=new Date(f.get('endedAt')).toISOString();if(Date.parse(endedAt)<Date.parse(startedAt))throw Error('Shift end must be after its start.');await mutate(v=>{const z=v.shifts.find(z=>z.id===key);validateShiftMileage(v,key,a,b);audit(v,key,'shift correction', {start:z.startOdometer,end:z.endOdometer,startedAt:z.startedAt,endedAt:z.endedAt},{start:a,end:b,startedAt,endedAt,reason});z.startOdometer=a;z.endOdometer=b;z.startedAt=startedAt;z.endedAt=endedAt;});},'Save');$('#delete-shift').onclick=()=>confirmShiftDeletion(key);return;}if(action==='filter'){const from=$('#from').value,to=$('#to').value;if(from&&to&&from>to)throw Error('Choose an end date on or after the start date.');range={from,to};detailPage=0;reportView='custom';return render();}if(action==='export'){range=reportDateRange($('#from').value,$('#to').value);reportView='custom';const exportShifts=filtered(range);if(!exportShifts.length){render();return dialog('No completed shifts in this date range',`<p>No completed ${demoMode?'sample ':''}shifts match ${esc(range.from||'the beginning')} through ${esc(range.to||'today')}. No file was downloaded.</p><p class="muted">Sample records and real records are separate. Check the intended mode and History.</p>`,null,'Save','Done');}const rows=[['shift_id','shift_date','time_zone','started_at','ended_at','start_odometer_mi','end_odometer_mi','actual_miles','estimated_miles','estimate_status','deliveries_completed','delivery_runs','rate_per_mile','expected_reimbursement','scheduled_completed','delivered_by_requested_time','timing_rule','single_runs','batch_runs','sample_data'],...exportShifts.map(s=>[s.id,localDate(s.startedAt),s.timeZone,s.startedAt,s.endedAt,s.startOdometer,s.endOdometer,miles(s),'','unavailable',deliveriesFor(s).filter(d=>d.status==='delivered').length,state.runs.filter(r=>r.shiftId===s.id).length,s.rate,reimbursement(s),scheduledStats(deliveriesFor(s)).total,scheduledStats(deliveriesFor(s)).onTime,'at or before requested time; provisional',runCounts(s).single,runCounts(s).batch,demoMode?'YES':'NO'])];notify(`Exporting ${exportShifts.length} completed shifts (${range.from||'all dates'} through ${range.to||'today'}).`);render();return download(`delivery-${demoMode?'SAMPLE-':''}records-${localDate(now())}.csv`,'\ufeff'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n')+'\r\n','text/csv;charset=utf-8');}if(action==='backup')return backup();if(action==='restore'){if(demoMode)throw Error('Exit sample mode before restoring real records.');return $('#restore-file').click();}if(action==='delete-customer'||action==='delete-all-customers'){const all=action==='delete-all-customers',ids=all?state.customers.map(c=>c.id):[key];return dialog(all?'Delete all saved customers?':'Delete customer details?',`<p>${all?`This removes all ${ids.length} saved customers.`:'This removes the saved customer.'} Names, addresses and phone numbers in linked deliveries—including current orders—are also redacted. Shift mileage, delivery counts and reimbursement totals are kept. Previously downloaded backups are unchanged.</p><p class="muted">This cannot be undone in the app. Download a backup first if you may need these contacts.</p>`,async()=>{await mutate(v=>purgeCustomers(v,ids));notify(all?'All saved customers deleted. Shift totals kept.':'Customer details deleted.');},all?'Delete all customers':'Delete details');}}

try{await openDB(demoMode?'delivery-manager-demo':'delivery-manager');state=await read();if(demoMode&&!state.demoSeedVersion){state=createDemoData();await save(state);}if(demoMode&&ensureDemoCurrentShift(state)){await save(state);}if(applySettingsDefaults(state))await save(state);completeRuns(state);await save(state);render();if(!demoMode){const reconcile=()=>syncNotifications(state).catch(()=>{});reconcile();addEventListener('online',reconcile);navigator.serviceWorker?.addEventListener('message',e=>{if(e.data?.type==='open-eos'){if($('#modal').open)return notify('Close this form when ready to review your shift.');tab='shift';render();checkShiftReminder();}});document.addEventListener('visibilitychange',()=>{if(!document.hidden)reconcile();});setInterval(reconcile,60000);}setInterval(checkShiftReminder,30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkShiftReminder();});setTimeout(checkShiftReminder,1000);registerUpdates().catch(()=>{});}catch(e){$('#app').innerHTML='<main class="main"><h1>We couldn’t open your records.</h1><p>Local storage may be unavailable. Please reopen this app in a regular browser window. No records have been reset.</p></main>';}
window.addEventListener('online',()=>state&&render());window.addEventListener('offline',()=>state&&render());

function hasDog(address){return !!state.addressNotes?.[addressKey(address)]?.barkingDog;}
function dogWarning(address){return hasDog(address)?'<div class="dog-warning">Barking dog — be prepared before approaching the door.</div>':'';}
function completionNotes(deliveryId){const d=state.deliveries.find(x=>x.id===deliveryId);dialog('Delivery completed',`<p>Delivery time recorded.</p><label class="checkbox-label"><input type="checkbox" id="barking-dog" ${hasDog(d.address)?'checked':''}> Barking dog at this address</label><p class="muted">Remembered on this device for future deliveries to this address.</p>${d.phone?'<button type="button" class="primary" id="completion-text">Prepare customer text</button>':'<p>No customer phone number was entered.</p>'}`,null,'Save','Done');let pending=Promise.resolve();const check=$('#barking-dog');check.onchange=()=>{const checked=check.checked;pending=pending.then(()=>mutate(v=>{v.addressNotes??={};v.addressNotes[addressKey(d.address)]={barkingDog:checked};})).catch(e=>notify(e.message));};if($('#completion-text'))$('#completion-text').onclick=async()=>{await pending;customerMessage(d.id,'Delivery completed');};}
function showRoute(stops){dialog('Your route is ready',`<ol class="route-addresses">${stops.map((d,i)=>`<li><strong>Delivery ${i+1}</strong><div>${esc(navigationAddress(d.address))}</div>${dogWarning(d.address)}<a href="${esc(firstStopURL(d.address))}">Navigate to this stop only</a></li>`).join('')}</ol><a class="primary" href="${esc(mapsURL(stops.map(d=>d.address)))}">Open ${stops.length>1?'batch route':'directions'} in Apple Maps</a><p class="muted">The route ends at the final delivery. Check locations in Maps before driving.</p>`,null,'Save','Done');}
function tasksView(){const shift=active(),tasks=shift?.tasks||{};return header('Your kitchen tasks.','Check only the work you completed this shift.')+(!shift?'<div class="card">Start a shift to record tasks.</div>':`<form id="tasks-form" class="card">${TASK_GROUPS.map(g=>`<div class="task-group"><label class="checkbox-label"><input type="checkbox" data-task-parent="${g.id}" name="${g.id}" ${tasks[g.id]?'checked':''}> ${g.label}</label>${g.children?`<div data-task-children="${g.id}" class="task-children" ${tasks[g.id]?'':'hidden'}>${g.children.map(c=>`<label class="checkbox-label"><input type="checkbox" name="${g.id}:${c}" ${tasks[`${g.id}:${c}`]?'checked':''}> ${c}</label>`).join('')}</div>`:''}</div>`).join('')}<label for="special-task">Other / special tasks completed</label><textarea id="special-task" name="special" maxlength="1000">${esc(tasks.special||'')}</textarea><button class="primary" type="submit">Save tasks</button><p class="muted">Changes save automatically. Only completed tasks are included in Mike’s report.</p></form>`);}
function bindTasks(){const form=$('#tasks-form');if(!form)return;form.querySelectorAll('[data-task-parent]').forEach(c=>c.onchange=()=>{const children=form.querySelector(`[data-task-children="${c.dataset.taskParent}"]`);if(children){children.hidden=!c.checked;if(!c.checked)children.querySelectorAll('input').forEach(i=>i.checked=false);}});form.onchange=form.onsubmit=async e=>{e.preventDefault();const shiftId=active().id,f=new FormData(form),tasks={special:String(f.get('special')||'').trim()};for(const g of TASK_GROUPS){tasks[g.id]=f.has(g.id);for(const c of g.children||[])tasks[`${g.id}:${c}`]=f.has(g.id)&&f.has(`${g.id}:${c}`);}try{await mutate(v=>{v.shifts.find(s=>s.id===shiftId).tasks=tasks;});notify('Tasks saved for this shift.');}catch(e){notify(e.message);}};}
const renderBase=render;render=function(){renderBase();bindTasks();};
function checkShiftReminder(){const s=active();if(!s||document.hidden||$('#modal').open||busy||!reminderDue(s))return;dialog('Still on shift?',`<p>Delivery cutoff was over 30 minutes ago. If you’ve finished, record your ending mileage and prepare Mike’s report.</p><p>If you’re still working, we’ll remind you in 15 minutes.</p><button type="button" id="reminder-end" class="primary">End shift</button>`,null,'Save','Remind me in 15 minutes');const snooze=()=>mutate(v=>{const x=v.shifts.find(x=>x.id===s.id);if(x)x.reminderAfter=new Date(Date.now()+15*60000).toISOString();}).catch(e=>notify(e.message));$('#modal').querySelector('[data-close]').onclick=async()=>{await snooze();$('#modal').close();};$('#modal').oncancel=()=>{snooze();};$('#reminder-end').onclick=async()=>{await snooze();$('#modal').close();handle('end').catch(e=>notify(e.message));};}
function setupScanner(){const button=$('#scan-ticket'),input=$('#ticket-photo'),form=$('#modal form');button.onclick=()=>input.click();input.onchange=async()=>{const file=input.files[0];if(!file)return;const status=form.querySelector('#scan-status'),saveButton=form.querySelector('[type=submit]');button.disabled=true;saveButton.disabled=true;try{const result=await scanTicket(file,message=>{status.textContent=message;});if(!form.isConnected)return;for(const [key,selector] of Object.entries({name:'#customer',phone:'#phone',address:'#address',ticket:'#ticket'})){if(result[key])form.querySelector(selector).value=result[key];}status.textContent='Scan complete. Check the name, phone, address and ticket number before saving. Drinks, alcohol and scheduled time still need your confirmation.';}catch(e){if(form.isConnected)status.textContent='Could not read this photo. Try a closer, brighter photo or enter the details manually.';}finally{if(form.isConnected){button.disabled=false;saveButton.disabled=false;input.value='';}}};}

function notificationSettings(){const n=notificationStatus();return `<section class="card"><h2>Lock-screen shift reminders</h2><p class="muted">Free reminders at 9:00 p.m. Sunday–Thursday and 9:30 p.m. Friday–Saturday, if your shift is still open. Ending your shift cancels its reminder when online. Customer details stay on this device.</p>${demoMode?'<p>Notifications are disabled in sample mode.</p>':`${n.unsupported?`<p>${esc(n.unsupported)}</p>`:''}<p><strong>${n.enabled?'Enabled for this phone':'Not enabled'}</strong>${n.permission==='denied'?' · blocked in phone notification settings':''}</p>${n.pending?'<p class="dog-warning">Reminder update pending. Connect to the internet to finish scheduling or cancellation.</p>':''}${n.error?`<p class="error">${esc(n.error)}</p>`:''}${n.lastTest?`<p class="${n.lastTest.state==='failed'?'error':'hint'}" role="status" aria-live="polite">${esc(n.lastTest.message)}</p>`:''}<div class="actions">${n.enabled?`<button data-action="test-push" class="primary" ${n.lastTest?.state==='sending'?'disabled':''}>${n.lastTest?.state==='sending'?'Sending…':'Send test notification'}</button><button data-action="disable-push">Disable reminders</button>`:`<button data-action="enable-push" class="primary" ${n.unsupported?'disabled':''}>Enable lock-screen reminders</button>`}${n.pending?'<button data-action="retry-push">Retry connection</button>':''}</div><p class="muted">Focus settings and internet availability can delay alerts. Notification setup stays with this installation and isn’t included in backups.</p>`}</section>`;}
